 insert into public.fire_events(name,event_number,status) overriding system value values('TRUST ROLLBACK',7000000000000000004,'active') returning id into e;
 insert into public.fire_events(name,event_number,status) overriding system value values('TRUST OTHER',7000000000000000005,'active') returning id into e2;
 insert into trust_results values('enrollment is pending with random bearer and fingerprint',a->>'status'='pending' and t~'^[0-9a-f]{64}$' and length(a->>'fingerprint')=8);
 insert into trust_results values('pending token cannot list active events',public.worker_device_events(d,t)='[]');
 insert into trust_results values('wrong token cannot inspect profile',public.worker_device_profile(d,repeat('f',64)) is null);
 insert into trust_results values('HQ approves device',public.hq_decide_worker_device(d,'approved','צפון'));
 insert into trust_results values('roster never returns device or push tokens',not (public.hq_trusted_workers()::text like '%token%'));
 insert into trust_results values('approved device sees events',jsonb_array_length(public.worker_device_events(d,t))>=2);
 insert into trust_results values('invite filters equipment',public.hq_invite_trusted_workers(e,null,null,'משאבה')=0);
 insert into trust_results values('invite targets approved equipment owner',public.hq_invite_trusted_workers(e,array[d],null,'מפוח')=1);
 insert into trust_results values('duplicate invite is idempotent',public.hq_invite_trusted_workers(e,array[d])=0);
 insert into trust_results values('decline response accepted',public.worker_device_respond(d,t,e,'declined'));
 insert into trust_results values('decline does not register worker or start location',count_before=0);
 insert into trust_results values('approved device joins without event code',public.worker_secure_session_worker_valid(w,j->>'session_token'));
 insert into trust_results select 'join uses approved identity and no initial GPS',name='TRUST TEST' and phone='972500000001' and latitude is null and longitude is null from public.workers where id=w;
 insert into trust_results values('other token cannot update invitation',not public.worker_device_respond(d2,b->>'token',e,'accepted'));
 insert into trust_results values('revoke approval works',public.hq_decide_worker_device(d,'revoked'));
 insert into trust_results values('revocation immediately invalidates linked event session',not public.worker_secure_session_worker_valid(w,j->>'session_token'));
 insert into trust_results values('revoked device cannot list active events',public.worker_device_events(d,t)='[]');
 insert into trust_results values('anon cannot dispatch push',not has_function_privilege('anon','public.service_claim_worker_invitation_push(uuid)','execute'));
 insert into trust_results values('tables have RLS and no direct anonymous read',not has_table_privilege('anon','public.worker_trusted_devices','select') and (select relrowsecurity from pg_class where oid='public.worker_trusted_devices'::regclass));
