create temp table trust_results(name text,passed boolean) on commit drop;
do $$declare a jsonb;b jsonb;t text;d uuid;d2 uuid;e uuid;e2 uuid;m uuid;j jsonb;w uuid;count_before bigint;begin
 perform set_config('request.jwt.claim.sub','',true);
 a:=public.worker_request_device_approval('TRUST TEST','972500000001',array['מפוח']);d:=(a->>'id')::uuid;t:=a->>'token';
 begin perform public.worker_device_join_event(d,t,e);insert into trust_results values('pending token cannot join',false);exception when insufficient_privilege then insert into trust_results values('pending token cannot join',true);end;
 begin perform public.hq_trusted_workers();insert into trust_results values('anonymous cannot inspect roster',false);exception when insufficient_privilege then insert into trust_results values('anonymous cannot inspect roster',true);end;
 select user_id into m from public.hq_managers limit 1;perform set_config('request.jwt.claim.sub',m::text,true);
 select count(*) into count_before from public.workers where event_id=e;
 j:=public.worker_device_join_event(d,t,e);w:=(j->>'worker_id')::uuid;
 b:=public.worker_device_join_event(d,t,e);insert into trust_results values('repeat join uses same worker',b->>'worker_id'=j->>'worker_id');
 b:=public.worker_device_join_event(d,t,e2);insert into trust_results values('same approved identity can join another active event',b->>'event_id'=e2::text and b->>'worker_id'<>j->>'worker_id');
 b:=public.worker_request_device_approval('OTHER TEST','972500000002','{}');d2:=(b->>'id')::uuid;
 update public.fire_events set status='ended' where id=e;
 perform public.hq_decide_worker_device(d,'approved');
 begin perform public.worker_device_join_event(d,t,e);insert into trust_results values('closed event rejects approved device',false);exception when raise_exception then insert into trust_results values('closed event rejects approved device',true);end;
end $$;
select * from trust_results;
do $$begin if exists(select 1 from trust_results where not passed) then raise exception 'Trust regression failure';end if;end $$;
